using System.Buffers.Binary;
using System.IO.Compression;
using System.Text;
using System.Text.Json.Nodes;
using Sli.Server.Storage.Archive;
using Xunit;

namespace Sli.Server.Tests.Storage;

public sealed class CompactLinkMetadataTests
{
    // Generated by the frozen Python encode_link_metadata; compare raw bytes, not platform deflate bytes.
    const string Nonmonotonic = "";
    const string Legacy = "";
    const string Bigint = "";
    const string MaxBigint = "";

    static JsonObject Row(long eventId = 1, int entityId = 2, int roleId = 3) => new()
    {
        ["event_id"] = eventId, ["entity_id"] = entityId, ["role_id"] = roleId,
        ["created_at"] = "2026-07-14T00:00:00Z"
    };

    [Fact]
    public void Roundtrip_binds_identity_dictionary_float32_and_nonmonotonic_microseconds()
    {
        var laterId = Row(2, 9, 3);
        laterId["confidence"] = 0.7; laterId["extracted_from"] = "xml"; laterId["created_at"] = "2026-07-14T00:00:00.123456Z";
        var firstId = Row(1, 7, 1);
        firstId["confidence"] = 1.0; firstId["extracted_from"] = "event_data"; firstId["created_at"] = "2026-07-14T00:00:05.654321Z";
        // The archive must not persist content that happens to be present in the input.
        laterId["record_xml"] = "<Event>synthetic</Event>";
        var encoded = CompactLinkMetadata.Encode([laterId, firstId]);
        foreach (var decoded in new[] { CompactLinkMetadata.Decode(encoded.Compressed), CompactLinkMetadata.Decode(Convert.FromBase64String(Nonmonotonic)) })
        {
            Assert.Equal(new[] { (1L, 7, 1), (2L, 9, 3) }, decoded.Select(x => (x["event_id"]!.GetValue<long>(), x["entity_id"]!.GetValue<int>(), x["role_id"]!.GetValue<int>())));
            Assert.Equal("2026-07-14T00:00:05.654321Z", decoded[0]["created_at"]!.GetValue<string>());
            Assert.Equal("2026-07-14T00:00:00.123456Z", decoded[1]["created_at"]!.GetValue<string>());
            Assert.Equal(1.0, decoded[0]["confidence"]!.GetValue<double>());
            Assert.Equal((double)(float)0.7, decoded[1]["confidence"]!.GetValue<double>());
            Assert.Equal("event_data", decoded[0]["extracted_from"]!.GetValue<string>());
            Assert.Equal("xml", decoded[1]["extracted_from"]!.GetValue<string>());
            Assert.All(decoded, x => Assert.False(x.ContainsKey("record_xml")));
        }
        Assert.Equal(Raw(Convert.FromBase64String(Nonmonotonic)), Raw(encoded.Compressed));
        Assert.Equal("E0B35988B1C80BAEB3DBBED2D9FBD117F3C89C3BD4423A6C456405F3FD1AA1C2", encoded.Evidence["raw_sha256"]!.GetValue<string>());
        Assert.Equal("65C6629ED9A85100D93FEC4EABF9AE05165E588206F27CFC1BB8924932427ABD", encoded.Evidence["identity_sha256"]!.GetValue<string>());
        Evidence(encoded, 2);
        Assert.Equal(encoded.Compressed, CompactLinkMetadata.Encode([firstId, laterId]).Compressed);
    }

    [Theory]
    [InlineData(2_147_483_648L, Bigint, "166D34B7ED60FD3DE05DDB450DD001502A6F8B5C4E7DC1F0B39F212A2392827F")]
    [InlineData(long.MaxValue, MaxBigint, "C508A1E7FD07FCCC8D8187AF6B9C0F6ACB8025C8707CDC2FC043523F4587B05D")]
    public void Bigint_events_roundtrip_and_match_python_v2_bytes(long eventId, string source, string rawHash)
    {
        var encoded = CompactLinkMetadata.Encode([Row(), Row(eventId)]);
        Assert.Equal(new long[] { 1, eventId }, CompactLinkMetadata.Decode(encoded.Compressed).Select(x => x["event_id"]!.GetValue<long>()));
        Assert.Equal(new long[] { 1, eventId }, CompactLinkMetadata.Decode(Convert.FromBase64String(source)).Select(x => x["event_id"]!.GetValue<long>()));
        Assert.Equal(Raw(Convert.FromBase64String(source)), Raw(encoded.Compressed));
        Assert.Equal("SLILNK2\0", Encoding.ASCII.GetString(Raw(encoded.Compressed), 0, 8));
        Assert.Equal(rawHash, encoded.Evidence["raw_sha256"]!.GetValue<string>());
        Assert.All(CompactLinkMetadata.Decode(encoded.Compressed), x =>
        {
            Assert.Equal(1.0, x["confidence"]!.GetValue<double>());
            Assert.Equal("", x["extracted_from"]!.GetValue<string>());
            Assert.Equal("2026-07-14T00:00:00Z", x["created_at"]!.GetValue<string>());
        });
        Evidence(encoded, 2);
    }

    [Fact]
    public void Legacy_int32_format_and_identity_hash_are_unchanged()
    {
        var encoded = CompactLinkMetadata.Encode([Row()]);
        Assert.Equal("SLILNK1\0", Encoding.ASCII.GetString(Raw(encoded.Compressed), 0, 8));
        Assert.Equal(Raw(Convert.FromBase64String(Legacy)), Raw(encoded.Compressed));
        byte[] identity = new byte[10];
        BinaryPrimitives.WriteInt32LittleEndian(identity, 1);
        BinaryPrimitives.WriteInt32LittleEndian(identity.AsSpan(4), 2);
        BinaryPrimitives.WriteUInt16LittleEndian(identity.AsSpan(8), 3);
        Assert.Equal(ArchiveCodec.Hash(identity), encoded.Evidence["identity_sha256"]!.GetValue<string>());
        Assert.Equal(1L, Assert.Single(CompactLinkMetadata.Decode(encoded.Compressed))["event_id"]!.GetValue<long>());
        Assert.Equal(1L, Assert.Single(CompactLinkMetadata.Decode(Convert.FromBase64String(Legacy)))["event_id"]!.GetValue<long>());
        Evidence(encoded, 1);
    }

    [Theory]
    [InlineData(1L)]
    [InlineData(2_147_483_648L)]
    public void Corrupt_gzip_is_rejected_for_both_formats(long eventId)
    {
        var row = Row(eventId); row["confidence"] = 1.0; row["extracted_from"] = "xml";
        byte[] damaged = CompactLinkMetadata.Encode([row]).Compressed;
        damaged[damaged.Length / 2] ^= 0x40;
        Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Decode(damaged));
    }

    [Fact]
    public void Int64_overflow_duplicate_identity_and_int32_entity_overflow_are_rejected()
    {
        var overflow = Row(); overflow["event_id"] = 9_223_372_036_854_775_808UL;
        Assert.Contains("int64", Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Encode([overflow])).Message);
        var duplicate = Row();
        Assert.Contains("duplicate", Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Encode([duplicate, (JsonObject)duplicate.DeepClone()])).Message);
        overflow = Row(); overflow["entity_id"] = 2_147_483_648L;
        Assert.Contains("int32", Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Encode([overflow])).Message);
    }

    [Theory]
    [InlineData("event_id", "0")]
    [InlineData("entity_id", "-1")]
    [InlineData("role_id", "65536")]
    [InlineData("confidence", "1.1")]
    [InlineData("confidence", "-0.1")]
    [InlineData("created_at", "\"2026-07-14T00:00:00\"")]
    public void Invalid_metadata_is_rejected(string field, string value)
    {
        var row = Row(); row[field] = JsonNode.Parse(value);
        Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Encode([row]));
    }

    [Fact]
    public void Empty_metadata_block_is_rejected() => Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Encode([]));

    [Theory]
    [InlineData("magic")]
    [InlineData("header")]
    [InlineData("framing")]
    [InlineData("order")]
    [InlineData("dictionary")]
    [InlineData("identity")]
    public void Valid_gzip_does_not_hide_corrupt_compact_metadata(string fault)
    {
        byte[] raw = Raw(Convert.FromBase64String(Nonmonotonic));
        int offset = 12 + (int)BinaryPrimitives.ReadUInt32LittleEndian(raw.AsSpan(8));
        switch (fault)
        {
            case "magic": raw[0] ^= 1; break;
            case "header": raw[12] = (byte)'!'; break;
            case "framing": raw = raw[..^1]; break;
            case "order": raw.AsSpan(offset, 24).CopyTo(raw.AsSpan(offset + 24)); break;
            case "dictionary": BinaryPrimitives.WriteUInt16LittleEndian(raw.AsSpan(offset + 14), ushort.MaxValue); break;
            case "identity": BinaryPrimitives.WriteInt32LittleEndian(raw.AsSpan(offset + 4), 8); break;
        }
        using var stream = new MemoryStream();
        using (var gzip = new GZipStream(stream, CompressionLevel.Optimal, true)) gzip.Write(raw);
        Assert.Throws<InvalidDataException>(() => CompactLinkMetadata.Decode(stream.ToArray()));
    }

    static byte[] Raw(byte[] compressed)
    {
        using var input = new MemoryStream(compressed);
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream(); gzip.CopyTo(output); return output.ToArray();
    }

    static void Evidence((byte[] Compressed, JsonObject Evidence) encoded, int rows)
    {
        Assert.Equal(rows, encoded.Evidence["rows"]!.GetValue<int>());
        Assert.False(encoded.Evidence["content_persisted"]!.GetValue<bool>());
        Assert.Equal(Raw(encoded.Compressed).Length, encoded.Evidence["raw_bytes"]!.GetValue<int>());
        Assert.Equal(encoded.Compressed.Length, encoded.Evidence["compressed_bytes"]!.GetValue<int>());
        Assert.Equal(ArchiveCodec.Hash(encoded.Compressed), encoded.Evidence["compressed_sha256"]!.GetValue<string>());
    }
}
